CREATE TABLE IF NOT EXISTS users (
 id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(180) NOT NULL UNIQUE,
 password_hash VARCHAR(255) NOT NULL, avatar VARCHAR(600), university VARCHAR(120) NOT NULL,
 department VARCHAR(100), year INT, hostel VARCHAR(120), role ENUM('STUDENT','ADMIN') DEFAULT 'STUDENT',
 verified BOOLEAN DEFAULT FALSE, status ENUM('ACTIVE','SUSPENDED','BANNED','DELETED') DEFAULT 'ACTIVE',
 onboarding_complete BOOLEAN DEFAULT FALSE, interests JSON, preferences JSON,
 token_version INT DEFAULT 0, trust_score INT DEFAULT 50, average_rating DECIMAL(3,2) DEFAULT 0,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS auth_tokens (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL, token_hash CHAR(64) UNIQUE NOT NULL,purpose ENUM('VERIFY','RESET') NOT NULL,expires_at DATETIME NOT NULL,used_at DATETIME,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS circles (id INT AUTO_INCREMENT PRIMARY KEY,owner_id INT NOT NULL,name VARCHAR(100) NOT NULL,description TEXT,rules TEXT,university VARCHAR(120) NOT NULL,invite_code CHAR(32) UNIQUE NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(owner_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS circle_members (circle_id INT NOT NULL,user_id INT NOT NULL,joined_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(circle_id,user_id),FOREIGN KEY(circle_id) REFERENCES circles(id),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS items (
 id INT AUTO_INCREMENT PRIMARY KEY,owner_id INT NOT NULL,name VARCHAR(140) NOT NULL,slug VARCHAR(200) NOT NULL,
 category VARCHAR(40) NOT NULL,subcategory VARCHAR(60),description TEXT NOT NULL,item_condition ENUM('NEW','EXCELLENT','GOOD','USED') NOT NULL,
 condition_notes TEXT,location VARCHAR(150) NOT NULL,building VARCHAR(100),pickup_instructions TEXT,included TEXT,
 max_borrow_duration INT DEFAULT 168,status ENUM('ACTIVE','UNAVAILABLE','DRAFT','ARCHIVED','HIDDEN','DELETED') DEFAULT 'ACTIVE',
 circle_id INT,views INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 FOREIGN KEY(owner_id) REFERENCES users(id),FOREIGN KEY(circle_id) REFERENCES circles(id),INDEX(category,status,created_at),INDEX(owner_id,status)
);
CREATE TABLE IF NOT EXISTS uploads (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,url VARCHAR(600) NOT NULL,public_id VARCHAR(255) NOT NULL,kind VARCHAR(30) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS item_images (id INT AUTO_INCREMENT PRIMARY KEY,item_id INT NOT NULL,url VARCHAR(600) NOT NULL,public_id VARCHAR(255),position INT DEFAULT 0,FOREIGN KEY(item_id) REFERENCES items(id));
CREATE TABLE IF NOT EXISTS item_availability (id INT AUTO_INCREMENT PRIMARY KEY,item_id INT NOT NULL,start_time DATETIME NOT NULL,end_time DATETIME NOT NULL,FOREIGN KEY(item_id) REFERENCES items(id),CHECK(end_time>start_time));
CREATE TABLE IF NOT EXISTS item_rules (id INT AUTO_INCREMENT PRIMARY KEY,item_id INT NOT NULL,rule_text VARCHAR(300) NOT NULL,FOREIGN KEY(item_id) REFERENCES items(id));
CREATE TABLE IF NOT EXISTS favorites (user_id INT NOT NULL,item_id INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,item_id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(item_id) REFERENCES items(id));
CREATE TABLE IF NOT EXISTS borrow_requests (
 id INT AUTO_INCREMENT PRIMARY KEY,item_id INT NOT NULL,borrower_id INT NOT NULL,owner_id INT NOT NULL,start_time DATETIME NOT NULL,end_time DATETIME NOT NULL,
 purpose VARCHAR(300) NOT NULL,message VARCHAR(1000),status ENUM('REQUESTED','ACCEPTED','REJECTED','CANCELLED','COMPLETED') DEFAULT 'REQUESTED',reason VARCHAR(500),
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 FOREIGN KEY(item_id) REFERENCES items(id),FOREIGN KEY(borrower_id) REFERENCES users(id),FOREIGN KEY(owner_id) REFERENCES users(id),CHECK(end_time>start_time),INDEX(item_id,status,start_time,end_time),INDEX(borrower_id,status),INDEX(owner_id,status)
);
CREATE TABLE IF NOT EXISTS transactions (
 id INT AUTO_INCREMENT PRIMARY KEY,request_id INT NOT NULL UNIQUE,item_id INT NOT NULL,owner_id INT NOT NULL,borrower_id INT NOT NULL,
 status ENUM('ACCEPTED','HANDOVER_PENDING','HANDED_OVER','ACTIVE','RETURN_PENDING','RETURNED','COMPLETED','CANCELLED','OVERDUE','DISPUTED') DEFAULT 'ACCEPTED',
 owner_handover DATETIME,borrower_handover DATETIME,handover_time DATETIME,expected_return DATETIME NOT NULL,actual_return DATETIME,return_condition VARCHAR(30),return_notes TEXT,
 extension_time DATETIME,extension_status ENUM('REQUESTED','ACCEPTED','REJECTED'),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 FOREIGN KEY(request_id) REFERENCES borrow_requests(id),FOREIGN KEY(item_id) REFERENCES items(id),FOREIGN KEY(owner_id) REFERENCES users(id),FOREIGN KEY(borrower_id) REFERENCES users(id),INDEX(item_id,status),INDEX(borrower_id,status),INDEX(owner_id,status),INDEX(status,expected_return)
);
CREATE TABLE IF NOT EXISTS transaction_events (id INT AUTO_INCREMENT PRIMARY KEY,transaction_id INT NOT NULL,actor_id INT,state VARCHAR(30) NOT NULL,note VARCHAR(600),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(transaction_id) REFERENCES transactions(id),FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS handover_evidence (id INT AUTO_INCREMENT PRIMARY KEY,transaction_id INT NOT NULL,user_id INT NOT NULL,upload_id INT NOT NULL,FOREIGN KEY(transaction_id) REFERENCES transactions(id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(upload_id) REFERENCES uploads(id));
CREATE TABLE IF NOT EXISTS return_evidence (id INT AUTO_INCREMENT PRIMARY KEY,transaction_id INT NOT NULL,user_id INT NOT NULL,upload_id INT NOT NULL,FOREIGN KEY(transaction_id) REFERENCES transactions(id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(upload_id) REFERENCES uploads(id));
CREATE TABLE IF NOT EXISTS reviews (id INT AUTO_INCREMENT PRIMARY KEY,transaction_id INT NOT NULL,reviewer_id INT NOT NULL,reviewed_user_id INT NOT NULL,rating INT NOT NULL,communication_rating INT,punctuality_rating INT,item_care_rating INT,comment VARCHAR(1500) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(transaction_id,reviewer_id),CHECK(rating BETWEEN 1 AND 5),FOREIGN KEY(transaction_id) REFERENCES transactions(id),FOREIGN KEY(reviewer_id) REFERENCES users(id),FOREIGN KEY(reviewed_user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS notifications (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,type VARCHAR(40) NOT NULL,title VARCHAR(200) NOT NULL,link VARCHAR(200),is_read BOOLEAN DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),INDEX(user_id,is_read,id));
CREATE TABLE IF NOT EXISTS conversations (id INT AUTO_INCREMENT PRIMARY KEY,request_id INT UNIQUE NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(request_id) REFERENCES borrow_requests(id));
CREATE TABLE IF NOT EXISTS conversation_participants (conversation_id INT NOT NULL,user_id INT NOT NULL,last_read_id INT DEFAULT 0,PRIMARY KEY(conversation_id,user_id),FOREIGN KEY(conversation_id) REFERENCES conversations(id),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS messages (id INT AUTO_INCREMENT PRIMARY KEY,conversation_id INT NOT NULL,sender_id INT NOT NULL,body VARCHAR(4000) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(conversation_id) REFERENCES conversations(id),FOREIGN KEY(sender_id) REFERENCES users(id),INDEX(conversation_id,id));
CREATE TABLE IF NOT EXISTS disputes (id INT AUTO_INCREMENT PRIMARY KEY,transaction_id INT NOT NULL,raised_by INT NOT NULL,reason VARCHAR(80) NOT NULL,description TEXT NOT NULL,status ENUM('OPEN','UNDER_REVIEW','NEEDS_INFORMATION','RESOLVED','CLOSED') DEFAULT 'OPEN',previous_state VARCHAR(30),decision VARCHAR(80),resolution TEXT,resolved_by INT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(transaction_id) REFERENCES transactions(id),FOREIGN KEY(raised_by) REFERENCES users(id),FOREIGN KEY(resolved_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS dispute_evidence (id INT AUTO_INCREMENT PRIMARY KEY,dispute_id INT NOT NULL,upload_id INT NOT NULL,FOREIGN KEY(dispute_id) REFERENCES disputes(id),FOREIGN KEY(upload_id) REFERENCES uploads(id));
CREATE TABLE IF NOT EXISTS reports (id INT AUTO_INCREMENT PRIMARY KEY,reporter_id INT NOT NULL,target_type ENUM('ITEM','USER','MESSAGE') NOT NULL,target_id INT NOT NULL,reason VARCHAR(100) NOT NULL,description VARCHAR(1500),status ENUM('OPEN','RESOLVED') DEFAULT 'OPEN',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(reporter_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS audit_logs (id INT AUTO_INCREMENT PRIMARY KEY,admin_id INT NOT NULL,action VARCHAR(80) NOT NULL,target_type VARCHAR(40),target_id INT,reason TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(admin_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS user_badges (user_id INT NOT NULL,badge VARCHAR(60) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,badge),FOREIGN KEY(user_id) REFERENCES users(id));
